const COOKBOOK={"title": "ספר המתכונים של אמא דינה", "author": "דינה סופר גלברד", "categories": ["קובות", "ביצים ולביבות", "מאפים", "דגים", "מנות פתיחה", "ממולאים", "בשר", "עוף", "תוספות", "מרקים"], "recipes": [{"id": "r01", "title": "קובה בורגול", "category": "קובות", "blocks": [{"text": "כמות קובות: 30", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "למעטפת", "bold": true, "kind": "subheading"}, {"text": "1 ק\"ג בורגול דק (גרישה)", "bold": false, "kind": "ingredients"}, {"text": "1 כוס קמח (כוס חד־פעמית לשתייה קרה)", "bold": false, "kind": "ingredients"}, {"text": "600 מיליליטר עד ליטר מים", "bold": false, "kind": "ingredients"}, {"text": "כף מלח", "bold": false, "kind": "ingredients"}, {"text": "כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "½ קילו בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "5 בצלים קצוצים", "bold": false, "kind": "ingredients"}, {"text": "חופן פטרוזיליה קצוצה", "bold": false, "kind": "ingredients"}, {"text": "½ כוס צימוקים", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס צנוברים", "bold": false, "kind": "ingredients"}, {"text": "2 כפיות מלח", "bold": false, "kind": "ingredients"}, {"text": "3 כפיות בהרט", "bold": false, "kind": "ingredients"}, {"text": "כף פפריקה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס שמן לטיגון", "bold": false, "kind": "ingredients"}, {"text": "לבישול הקובות", "bold": true, "kind": "subheading"}, {"text": "מים", "bold": false, "kind": "ingredients"}, {"text": "כורכום", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "הכנת המעטפת", "bold": true, "kind": "subheading"}, {"text": "בקערה מכניסים את הבורגול, את המלח ואת הכורכום, מערבבת, מוסיפה את המים והקמח ולשה עד לקבלת בצק רך וגמיש.", "bold": false, "kind": "method"}, {"text": "מניחה את הבצק לנוח כחצי שעה.", "bold": false, "kind": "method"}, {"text": "הכנת המילוי", "bold": true, "kind": "subheading"}, {"text": "מחממים בסיר שמן ומטגנים את הבצלים עד להזהבה, לאחר מכן מוסיפים לסיר בשר, פטרוזיליה, צימוקים, צנוברים ותבלינים, מבשלים עד להשחמה של הבשר. את תערובת הבשר נסנן במסננת להוצאת הנוזלים. נניח לבשר להצטנן, לא ממלאים את הקובות כשהבשר עדיין חם.", "bold": false, "kind": "method"}, {"text": "מילוי הקובות", "bold": true, "kind": "subheading"}, {"text": "ניצור מהבצק כדורים בגודל של כדור טניס.", "bold": false, "kind": "method"}, {"text": "נפתח כל כדור על כף היד, נניח בתוכו כף וחצי מתערובת הבשר ונסגור בעדינות את הכדור. נמעך את הכדור עד ליצירת קובה שטוחה.", "bold": false, "kind": "method"}, {"text": "בישול הקובות", "bold": true, "kind": "subheading"}, {"text": "נמלא סיר גדול ועמוק במים עד ל-¾ הסיר, מוסיפים מלח, כורכום,", "bold": false, "kind": "method"}, {"text": "נוסיף 6 קובות אל תוך הסיר, מבשלים בערך 15 דקות, נוציא בעדינות רבה למסננת גדולה וכך ממשיכים הלאה.", "bold": false, "kind": "method"}, {"text": "לאחר מכן אפשר לטגן במחבת עם מעט שמן את הקובות (משני הצדדים) עד להשחמה.", "bold": false, "kind": "method"}, {"text": "בתיאבון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות קובות: 30", "imageSource": "Word: image7", "memory": "קובה בורגול אוכלים בערבי חג וימי שישי!", "image": "assets/album/dish-bulgur-approved.jpg"}, {"id": "r02", "title": "קובה פטטה", "category": "קובות", "blocks": [{"text": "כמות קובות: 15 יחידות", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "למעטפת", "bold": true, "kind": "subheading"}, {"text": "5 תפוחי אדמה גדולים", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "250 גר' בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "4 בצלים קצוצים", "bold": false, "kind": "ingredients"}, {"text": "כוס צימוקים", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס שמן לטיגון הבצל", "bold": false, "kind": "ingredients"}, {"text": "10 עלי כרפס קצוצים", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "½ 1 כפיות בהרט", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פפריקה אדומה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "לטיגון", "bold": true, "kind": "subheading"}, {"text": "2 ביצים טרופות", "bold": false, "kind": "ingredients"}, {"text": "½ כוס קמח תפוחי אדמה + כפית פפריקה, כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "הכנת עיסת תפוחי אדמה למעטפת", "bold": true, "kind": "subheading"}, {"text": "אל תוך סיר עמוק נכניס את תפוחי האדמה עם הקליפה, להוסיף כפית מלח ולבשל במשך 45 דק'.", "bold": false, "kind": "method"}, {"text": "לאחר הבישול נסנן, נקלף ונחצה את תפוחי האדמה.", "bold": false, "kind": "method"}, {"text": "נחמם את תפוחי האדמה במיקרוגל במשך 5 דקות על מנת לייבש את כל הנוזלים.", "bold": false, "kind": "method"}, {"text": "נעביר את תפוחי האדמה לקערה, נוסיף חצי כפית מלח ונמעך אותם לפירה. נניח את הפירה לקירור.", "bold": false, "kind": "method"}, {"text": "הכנת המילוי", "bold": true, "kind": "subheading"}, {"text": "בסיר נטגן את הבצלים עד להזהבה נוסיף את הבשר הטחון, התבלינים, צימוקים ועלי הכרפס. נטגן עד שהבשר יתבשל, לאחר מכן נניח אותו לקירור.", "bold": false, "kind": "method"}, {"text": "מילוי הקובות", "bold": true, "kind": "subheading"}, {"text": "לוקחים חופן מהפירה ויוצרים כדור בגודל של כדור טניס, עם האגודל פותחים את הכדור בעדינות ומכניסים שתי כפיות גדושות מתערובת הבשר המטוגן, סוגרים את הכדור ומועכים מעט עם כף היד.", "bold": false, "kind": "method"}, {"text": "טיגון הקובות", "bold": true, "kind": "subheading"}, {"text": "נחמם במחבת שמן לטיגון.", "bold": false, "kind": "method"}, {"text": "בקערה אחת נכין תערובת קמח תפוחי האדמה ותבלינים ובשנייה נטרוף 2 ביצים.", "bold": false, "kind": "method"}, {"text": "נטבול את הקובות בתערובת הקמח ולאחר מכן בבלילת הביצים.", "bold": false, "kind": "method"}, {"text": "נטגן את הקובה במחבת משני הצדדים עד להשחמה.", "bold": false, "kind": "method"}, {"text": "בתיאבון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות קובות: 15 יחידות", "memory": "את הקובה פטטה הכנו בימי שישי וחגים"}, {"id": "r03", "title": "קובה סלק", "category": "קובות", "blocks": [{"text": "קובה סלק מכינים ביום שישי", "bold": false, "kind": "intro"}, {"text": "כמות קובות: 25", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "למרק", "bold": true, "kind": "subheading"}, {"text": "3 סלק - חתוך לקוביות", "bold": false, "kind": "ingredients"}, {"text": "1 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "3 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "1 כפית בהרט", "bold": false, "kind": "ingredients"}, {"text": "מעט שמן לטיגון", "bold": false, "kind": "ingredients"}, {"text": "למעטפת", "bold": true, "kind": "subheading"}, {"text": "500 גרם סולת", "bold": false, "kind": "ingredients"}, {"text": "½1 כוסות מי ברז", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "500 גרם בשר טחון מס' 2", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "כפית בהרט", "bold": false, "kind": "ingredients"}, {"text": "חופן עלי כרפס קצוצים", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "הכנת המרק", "bold": true, "kind": "subheading"}, {"text": "בסיר גדול של 7 ליטר נטגן בצל קצוץ עד להשחמה, נוסיף סלק אדום חתוך לקוביות ונמלא את הסיר במי ברז עד 0.75 מהסיר. נבשל עד להתרככות הסלק, נוסיף למרק לימון סחוט, סוכר, מלח ובהרט ונמשיך לבשל.", "bold": false, "kind": "method"}, {"text": "הכנת הבצק למעטפת", "bold": true, "kind": "subheading"}, {"text": "בקערה נערבב סולת, מלח ומי ברז. נלוש את התערובת ונניח בצד למשך רבע שעה.", "bold": false, "kind": "method"}, {"text": "מילוי הקובות והוספתן למרק", "bold": true, "kind": "subheading"}, {"text": "נכין מראש קערת מים בצד השולחן, לצורך העבודה עם העיסה עלינו להרטיב את ידינו מדי פעם תוך כדי העבודה.", "bold": false, "kind": "method"}, {"text": "בקערה נוספת נכין את התערובת למילוי: נערבב בשר טחון, מלח, פלפל שחור, בהרט ועלי סלרי קצוצים דק.", "bold": false, "kind": "method"}, {"text": "את עיסת הסולת נחלק לכדורים (בערך 25), לאחר יצירת הכדורים נפתח כל כדור בנפרד על כף היד הרטובה ונמלא בתערובת הבשר.", "bold": false, "kind": "method"}, {"text": "הערה חשובה: כדור הסולת צריך להיות בגודל של פינג פונג, בעת פתיחת הכדור נשים לב שאנחנו יוצרים שכבה לא דקה מדי כדי שהכדור לא יתפרק בבישול אך מספיק דקה כדי שנוזלי המרק יצליחו לחדור את שכבת הבצק של הקובה. כלל אצבע - עדיף שהקובה תתפרק קצת בסיר מאשר שתהיה עבה ומגושמת.", "bold": false, "kind": "method"}, {"text": "לאחר מילוי כל הקובות נניח אותן בסיר עם מרק הסלק ומבשלים במשך חצי שעה, על להבה בינונית.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות קובות: 25", "image": "assets/album/family-13.jpg", "imageSource": "Word: image10", "memory": "קובה סלק אוכלים ביום שישי בצהריים יחד עם קערת אורז לבן"}, {"id": "r04", "title": "קובה דלעת", "category": "קובות", "blocks": [{"text": "כמות קובות: 25", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "למעטפת", "bold": true, "kind": "subheading"}, {"text": "500 גרם סולת", "bold": false, "kind": "ingredients"}, {"text": "½1 כוסות מי ברז", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "למרק", "bold": true, "kind": "subheading"}, {"text": "1 בצל קצוץ", "bold": false, "kind": "ingredients"}, {"text": "½ קילו דלעת חתוכה לקוביות", "bold": false, "kind": "ingredients"}, {"text": "150 גר' רסק עגבניות (½1 קופסאות קטנות)", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "3 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור טחון", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "250 גר' בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "10 עלי סלרי קצוצים", "bold": false, "kind": "ingredients"}, {"text": "1בצל קצוץ", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור טחון", "bold": false, "kind": "ingredients"}, {"text": "0.25 כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "הכנת הבצק למעטפת", "bold": true, "kind": "subheading"}, {"text": "בקערה נערבב סולת, מלח ומי ברז. נלוש את התערובת ונניח בצד למשך חצי שעה.", "bold": false, "kind": "method"}, {"text": "הכנת המרק", "bold": true, "kind": "subheading"}, {"text": "בסיר גדול עמוק ורחב מטגנים את הבצל להשחמה, לאחר מכן נוסיף רסק עגבניות, מלח, פלפל, לימון, סוכר, קוביות דלעת ונוסיף מים לסיר עד ¾ כיסוי של הסיר.", "bold": false, "kind": "method"}, {"text": "נביא את המרק לרתיחה (וניתן לדלעת להתבשל) ותוך כדי נמלא את הקובות.", "bold": false, "kind": "method"}, {"text": "מילוי הקובות והוספתן למרק", "bold": true, "kind": "subheading"}, {"text": "נכין מראש קערת מים בצד השולחן, לצורך העבודה עם העיסה עלינו להרטיב את ידינו מדי פעם תוך כדי העבודה.", "bold": false, "kind": "method"}, {"text": "בקערה נוספת נכין את התערובת למילוי: נערבב את הבשר עם בצל קצוץ, מלח, פלפל, כורכום ועלי הסלרי הקצוצים.", "bold": false, "kind": "method"}, {"text": "את עיסת הסולת נחלק לכדורים (בערך 25), לאחר יצירת הכדורים נפתח כל כדור בנפרד על כף היד הרטובה ונמלא בתערובת הבשר.", "bold": false, "kind": "method"}, {"text": "הערה חשובה: כדור הסולת צריך להיות בגודל של פינג פונג, בעת פתיחת הכדור נשים לב שאנחנו יוצרים שכבה לא דקה מדי כדי שהכדור לא יתפרק בבישול אך מספיק דקה כדי שנוזלי המרק יצליחו לחדור את שכבת הבצק של הקובה. כלל אצבע - עדיף שהקובה תתפרק קצת בסיר מאשר שתהיה עבה ומגושמת.", "bold": false, "kind": "method"}, {"text": "לאחר מילוי כל הקובות נניח אותן בסיר, לאחר שוידאנו כי הדלעת התבשלה.", "bold": false, "kind": "method"}, {"text": "נכסה את הסיר במכסה ונבשל על להבה בינונית במשך כ- 25 דקות נוספות.", "bold": false, "kind": "method"}, {"text": "בתיאבון", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות קובות: 25", "memory": "את הקובה דלעת אכלנו באמצע שבוע"}, {"id": "r05", "title": "קובה במיה", "category": "קובות", "blocks": [{"text": "כמות קובות: 25", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "למעטפת", "bold": true, "kind": "subheading"}, {"text": "½ קילו סולת", "bold": false, "kind": "ingredients"}, {"text": "½1 כוסות מי ברז", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "למרק", "bold": true, "kind": "subheading"}, {"text": "נוסח המקור — טור 1", "bold": true, "kind": "subheading"}, {"text": "שקית סנפרוסט במיה", "bold": false, "kind": "ingredients"}, {"text": "צרור פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "1 בצל קצוץ", "bold": false, "kind": "ingredients"}, {"text": "200 גר' רסק עגבניות (2 קופסאות קטנות)", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "כף סוכר", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "נוסח המקור — טור 2", "bold": true, "kind": "subheading"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "½ כפית כמון", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "כ-12 כוסות מים", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "נוסח המקור — טור 1", "bold": true, "kind": "subheading"}, {"text": "250 גר' בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "10 עלי סלרי קצוצים (?)", "bold": false, "kind": "ingredients"}, {"text": "צרור פטרוזיליה קצוצה", "bold": false, "kind": "ingredients"}, {"text": "1 בצל קצוץ", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית פלפל שחור.", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית בהרט.", "bold": false, "kind": "ingredients"}, {"text": "נוסח המקור — טור 2", "bold": true, "kind": "subheading"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור טחון", "bold": false, "kind": "ingredients"}, {"text": "¼ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "½1 כפיות כמון", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "שלב ראשון: הכנת הבצק", "bold": true, "kind": "subheading"}, {"text": "מוסיפים לקערה את הסולת, המים והמלח, מערבבים ומשאירים את הבצק לנוח במשך חצי שעה.", "bold": false, "kind": "method"}, {"text": "שלב שני: הכנת המרק", "bold": true, "kind": "subheading"}, {"text": "בסיר גדול עמוק ורחב מטגנים את הבצל להזהבה, לאחר מכן מוסיפים רסק עגבניות, מלח, פלפל שחור, לימון, סוכר וכמון - מערבבים קלות ומוסיפים את הבמיה. מטגנים מעט את הבמיה ולאחר מכן מוסיפים מים למרק (כ-12 כוסות). נביא את המרק לרתיחה ותוך כדי נמלא את הקובות.", "bold": false, "kind": "method"}, {"text": "שלב שלישי: מילוי הקובות והוספתן למרק", "bold": true, "kind": "subheading"}, {"text": "נערבב בקערה את הבשר עם בצל אחד קצוץ, מלח, פלפל, כורכום כמון, וצרור פטרוזיליה קצוצה.", "bold": false, "kind": "method"}, {"text": "לצורך העבודה עם העיסה נמלא קערה במים ונדאג להרטיב את ידינו תוך כדי העבודה.", "bold": false, "kind": "method"}, {"text": "את עיסת הסולת נחלק לכדורים (בערך 25), לאחר יצירת הכדורים נפתח כל כדור בנפרד על כף היד הרטובה ונמצא בבשר הטחון. לאחר מילוי כל הקובות נניח אותן בסיר, נכסה את הסיר במכסה ונבשל על להבה בינונית במשך כ- 25 דקות נוספות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["ברשימת המצרכים המקורית יש שני טורים, ובהם כפילויות והבדלים בתיבול. נשמרו הטורים לצורך בירור; אין לחבר את הכמויות הכפולות."], "servings": "כמות קובות: 25", "image": "assets/album/shoot-bamia.jpg", "imageSource": "Word: image11", "memory": "את הקובה במיה אכלנו גם ביום שישי בצהרים"}, {"id": "r06", "title": "קובה חומוס", "category": "קובות", "blocks": [{"text": "כמות קובות: 13-15", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "למעטפת", "bold": true, "kind": "subheading"}, {"text": "3 כוסות סולת", "bold": false, "kind": "ingredients"}, {"text": "3 כוסות בורגול דק (גרישה)", "bold": false, "kind": "ingredients"}, {"text": "2.5 כוסות מי ברז", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "למרק", "bold": true, "kind": "subheading"}, {"text": "1 בצל", "bold": false, "kind": "ingredients"}, {"text": "2 גזר גדול", "bold": false, "kind": "ingredients"}, {"text": "2 קישואים בינוניים", "bold": false, "kind": "ingredients"}, {"text": "4 גבעולי סלרי עם העלים שלהם (העלים למילוי)", "bold": false, "kind": "ingredients"}, {"text": "כוס וחצי גרגירי חומוס של סנפרוסט", "bold": false, "kind": "ingredients"}, {"text": "150-200 גרם רסק עגבניות", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל", "bold": false, "kind": "ingredients"}, {"text": "2 כפיות מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "כפית כמון", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית סוכר", "bold": false, "kind": "ingredients"}, {"text": "10 כוסות מי ברז", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "1 בצל גדול", "bold": false, "kind": "ingredients"}, {"text": "10 עלים קצוצים של הסלרי", "bold": false, "kind": "ingredients"}, {"text": "½ קילו בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "כף שמן", "bold": false, "kind": "ingredients"}, {"text": "½ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½1 כפית כמון", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "הכנת המרק", "bold": true, "kind": "subheading"}, {"text": "קוצצים את הבצל ומטגנים עד להזהבה, מוסיפים מעליו את רסק העגבניות.", "bold": false, "kind": "method"}, {"text": "חותכים את הגזר לעיגולים בעובי חצי ס\"מ, קישואים לקוביות, גבעולי הסלרי קצוץ לא דק וחומוס מוסיפים לסיר. נותנים להכל 2 דקות טיגון יחד. מוסיפים את התבלינים והמים ומבשלים במכסה סגור עד לרתיחה.", "bold": false, "kind": "method"}, {"text": "הכנת המילוי", "bold": true, "kind": "subheading"}, {"text": "קוצצים את הבצל ועלי הסלרי קטן, לשים עם שאר המצרכים.", "bold": false, "kind": "method"}, {"text": "הכנת המעטפת", "bold": true, "kind": "subheading"}, {"text": "מוסיפים את כל המצרכים ולשים. בידיים רטובות קורצים עיגולים לגודל של כדור פינג פונג ומעגלים אותם.", "bold": false, "kind": "method"}, {"text": "מילוי הקובות והוספתן למרק", "bold": true, "kind": "subheading"}, {"text": "משטחים את הכדור וממלאים אותו בכמות נדיבה של המילוי, סוגרים ומעגלים חזרה לצורת כדור. פעולת השיטוח לצורך הצורה המזוהה עם הקובה תיעשה לפני הזריקה לתבשיל.", "bold": false, "kind": "method"}, {"text": "יש להנמיך את האש לפני זריקת הקובות לתבשיל.", "bold": false, "kind": "method"}, {"text": "את יתרת המילוי (אם נשאר) ניתן לקבב ולהכניס לתבשיל.", "bold": false, "kind": "method"}, {"text": "מבשלים למשך חצי שעה על אש נמוכה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות קובות: 13-15", "image": "assets/album/shoot-hummus.jpg", "imageSource": "Word: image13", "memory": "את הקובה חומוס אכלנו ביום שלישי"}, {"id": "r07", "title": "עג'ה", "category": "ביצים ולביבות", "blocks": [{"text": "כמות מנות: 4", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "4 ביצים", "bold": false, "kind": "ingredients"}, {"text": "צרור פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "5 ענפי בצל ירוק", "bold": false, "kind": "ingredients"}, {"text": "1 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "חצי כוס קמח מצה/קמח רגיל", "bold": false, "kind": "ingredients"}, {"text": "מלח, פלפל", "bold": false, "kind": "ingredients"}, {"text": "1 כפית בהרט", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "קוצצים את הבצל, הבצל הירוק והפטרוזיליה.", "bold": false, "kind": "method"}, {"text": "מניחים בתוך הקערה מוסיפים את הביצים התבלינים והקמח ומערבבים הכל יחד.", "bold": false, "kind": "method"}, {"text": "במחבת מחממים מעט שמן שופכים את כל הבלילה למחבת ומבשלים על להבה נמוכה עד שהתחתית משחימה ואז הופכים לצד השני עד להשחמה קלה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 4", "memory": "עג'ה היא חביתת ירק עיראקית"}, {"id": "r08", "title": "ערוק (לביבות ירק)", "category": "ביצים ולביבות", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "3 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "3 תפוחי אדמה מגורדים בינוני וסחוטים היטב ללא נוזלים", "bold": false, "kind": "ingredients"}, {"text": "10 גבעולי פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "1 עגבניה קצוצה (לא חובה)", "bold": false, "kind": "ingredients"}, {"text": "5 ביצים", "bold": false, "kind": "ingredients"}, {"text": "1 כוס קמח רגיל", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית בהרט", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "מערבבים היטב את כל המצרכים יחד בקערה גדולה.", "bold": false, "kind": "method"}, {"text": "במחבת מחממים שמן. צרים לביבות ומוזגים אותן באמצעות תרבד עמוק למחבת.", "bold": false, "kind": "method"}, {"text": "מטגנים עד להשחמה משני הצדדים.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r09", "title": "עג'ה בג'בן", "category": "ביצים ולביבות", "blocks": [{"text": "כמות מנות: 4", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "100 גרם גבינה עיראקית (אפשר למצוא אצל משק עברי)", "bold": false, "kind": "ingredients"}, {"text": "6 ביצים", "bold": false, "kind": "ingredients"}, {"text": "1 בצל גדול", "bold": false, "kind": "ingredients"}, {"text": "חופן עלי פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "2 כפות קמח", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "שמן לטיגון", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "במחבת גדולה, לטגן את הבצל הקצוץ עד להשחמה, בקערה לגרד את הגבינה ולהוסיף את הביצים פטרוזיליה קמח מלח ופלפל, לערבב הכל יחד.", "bold": false, "kind": "method"}, {"text": "להניח הכל מעל הבצל המטוגן, לטגן על להבה נמוכה עד להשחמה לאחר מכן להפוך לצד השני.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 4"}, {"id": "r10", "title": "מפרקה (שקשוקה ירוקה)", "category": "ביצים ולביבות", "blocks": [{"text": "כמות מנות: 4", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "2 חבילות של עלי מנגולד", "bold": false, "kind": "ingredients"}, {"text": "2 בצלים", "bold": false, "kind": "ingredients"}, {"text": "3 גבעולים של בצל ירוק", "bold": false, "kind": "ingredients"}, {"text": "1 לוף (פרסה/ כרישה)", "bold": false, "kind": "ingredients"}, {"text": "2 עגבניות קלופות", "bold": false, "kind": "ingredients"}, {"text": "8 שיני שום קלוף", "bold": false, "kind": "ingredients"}, {"text": "6 ביצים", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל", "bold": false, "kind": "ingredients"}, {"text": "½ כפית כמון", "bold": false, "kind": "ingredients"}, {"text": "¼ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "½ לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "מחממים שמן בתוך סיר רחב, מוסיפים בצלים קצוצים מטגנים עד להזהבה, מוסיפים את המנגולד השטוף והפרוס לפרוסות דקות את הבצל הירוק את השום הלוף (פרוסות עגולות) ואת העגבניות לחתוך לקוביות, להוסיף את התבלינים ורבע כוס מים, לבשל עד להתרככות, לשבור את הביצים מעל הכל ולפזר מעט כמון.", "bold": false, "kind": "method"}, {"text": "בתיאבון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 4"}, {"id": "r11", "title": "לביבות כרובית", "category": "ביצים ולביבות", "blocks": [{"text": "כמות מנות: 35 יח'", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 כרובית גדולה", "bold": false, "kind": "ingredients"}, {"text": "1 בצל קצוץ דק", "bold": false, "kind": "ingredients"}, {"text": "5 גבעולים בצל ירוק", "bold": false, "kind": "ingredients"}, {"text": "1 קישוא מגורד", "bold": false, "kind": "ingredients"}, {"text": "2 גזרים מגורדים", "bold": false, "kind": "ingredients"}, {"text": "חופן פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "חופן כוסברה", "bold": false, "kind": "ingredients"}, {"text": "1 כוס בורגול דק (מושרה במים רותחים)", "bold": false, "kind": "ingredients"}, {"text": "5 ביצים", "bold": false, "kind": "ingredients"}, {"text": "3 כפות חרדל דיז'ון", "bold": false, "kind": "ingredients"}, {"text": "3 כפות מיונז", "bold": false, "kind": "ingredients"}, {"text": "3 כפיות מלח", "bold": false, "kind": "ingredients"}, {"text": "2 כפיות פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "להרתיח את הכרובית עד לריכוך מלא, לסנן, בקערה גדולה למעוך את הכרובית ולהוסיף את שאר המרכיבים הרשומים לעיל ונערבב הכל יחד.", "bold": false, "kind": "method"}, {"text": "ניצור כדורים בגודל פינג פונג, נניח נייר אפייה משומן מעט על מגש התנור ונאפה בחום של 200 מעלות במשך חצי שעה עד להשחמה.", "bold": false, "kind": "method"}, {"text": "אפשר לפזר שומשום מעל.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 35 יח'", "image": "assets/r11.jpg", "imageSource": "Word: image16"}, {"id": "r12", "title": "לביבות טונה", "category": "ביצים ולביבות", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "3 קופסאות טונה בשמן (לסנן מעט את השמן)", "bold": false, "kind": "ingredients"}, {"text": "בטטה אחת מגורדת דק", "bold": false, "kind": "ingredients"}, {"text": "2 גזרים מגורדים", "bold": false, "kind": "ingredients"}, {"text": "1 בצל מגורד", "bold": false, "kind": "ingredients"}, {"text": "בצל ירוק שני ענפים", "bold": false, "kind": "ingredients"}, {"text": "חצי צרור פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "חצי צרור כוסברה", "bold": false, "kind": "ingredients"}, {"text": "3 ביצים", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית פפריקה", "bold": false, "kind": "ingredients"}, {"text": "3 כפות רוטב סויה", "bold": false, "kind": "ingredients"}, {"text": "5 כפות פירורי לחם", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לערבב היטב את כל המרכיבים במג'ימיקס.", "bold": false, "kind": "method"}, {"text": "להניח במקרר לרבע שעה.", "bold": false, "kind": "method"}, {"text": "במגש גדול על נייר אפייה נניח את הלביבות שיצרנו, התיזו מעט שמן (תרסיס שמן).", "bold": false, "kind": "method"}, {"text": "לאפות בתנור במשך 20 דק' בחום של 200 מעלות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "", "image": "assets/r12.jpg", "imageSource": "Word: image17"}, {"id": "r13", "title": "סמבוסק בטאווה (חומוס)", "category": "מאפים", "blocks": [{"text": "כמות מנות: 35-40", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "ישנן שתי אופציות להכנת הבצק, בצק עם שמרים או בצק ללא שמרים. בחרו מה שנוח לכן:", "bold": true, "kind": "subheading"}, {"text": "בצק עם שמרים:", "bold": true, "kind": "subheading"}, {"text": "1 ק\"ג קמח", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "1 כף סוכר", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמרים", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "2 ½ כוסות מים פושרים.", "bold": false, "kind": "ingredients"}, {"text": "בצק ללא שמרים:", "bold": true, "kind": "subheading"}, {"text": "1 ק\"ג קמח", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "1 כף סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 שקית אבקת אפיה", "bold": false, "kind": "ingredients"}, {"text": "¾ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "2 כוסות מים פושרים או 2 כוסות מים בהם בושלו גרגירי החומוס", "bold": false, "kind": "ingredients"}, {"text": "למילוי:", "bold": true, "kind": "subheading"}, {"text": "שקית 800 גר' של גרגירי חומוס סנפרוסט.", "bold": false, "kind": "ingredients"}, {"text": "3 בצלים גדולים", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פפריקה אדומה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "3 כפות כמון", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח.", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס שמן לטיגון הבצל", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לערבב את כל המצרכים לבצק ולהתפיח במשך חצי שעה.", "bold": false, "kind": "method"}, {"text": "המילוי:", "bold": true, "kind": "subheading"}, {"text": "לבשל בסיר עמוק עם מי ברז את גרגירי החומוס עם כפית מלח עד לריכוך (במשך חצי שעה).", "bold": false, "kind": "method"}, {"text": "במעבד מזון: נכניס את גרגירי החומוס המבושלים והמסוננים נוסיף את הבצל המטוגן, נוסיף את התבלינים ונטחן יחד ,(אפשר לטחון גס או משחתי, כל אחד איך שהוא אוהב את המרקם).", "bold": false, "kind": "method"}, {"text": "לאחר שהבצק תפח יש לחלקו לכדורים בגודל של כדור קצת יותר גדול מפינג פונג, לרדד כל כדור לעובי של פחות מחצי ס\"מ, למלא בתערובת הטחונה ולסגור לצורת כיסון.", "bold": false, "kind": "method"}, {"text": "לעיתים לאחר מילוי מרבית כדורי הבצק, שאר הכדורים אשר ממתינים לתורם להתמלא, עשויים לתפוח מידי. לפני שפונים למלא אותם, צריך לשטח אותם מעט באמצעות האצבעות בתנועות טפיחה קלות, המכונות בעיראקית \"לצ'נג\". באופן הזה, האוויר המיותר יוצא החוצה והבצק ראוי להמשך עבודה.", "bold": false, "kind": "method"}, {"text": "במחבת:", "bold": true, "kind": "subheading"}, {"text": "על להבה בינונית נשים שמן לטיגון (לא שמן עמוק), נטגן מכל צד עד להשחמה בערך שתי דק' מכל צד. בתאבון!", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 35-40", "image": "assets/album/shoot-sambusak-hummus.jpg", "imageSource": "Word: image19"}, {"id": "r14", "title": "בסבוסה", "category": "מאפים", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 כוס סולת", "bold": false, "kind": "ingredients"}, {"text": "1 כוס קמח", "bold": false, "kind": "ingredients"}, {"text": "1 כוס סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "3 ביצים", "bold": false, "kind": "ingredients"}, {"text": "1 כוס מיץ תפוזים", "bold": false, "kind": "ingredients"}, {"text": "2 סוכר וניל", "bold": false, "kind": "ingredients"}, {"text": "2 אבקת אפייה", "bold": false, "kind": "ingredients"}, {"text": "1 כוס קוקוס", "bold": false, "kind": "ingredients"}, {"text": "לסירופ:", "bold": true, "kind": "subheading"}, {"text": "½ 1 כוסות סוכר", "bold": false, "kind": "ingredients"}, {"text": "חצי לימון", "bold": false, "kind": "ingredients"}, {"text": "2 כפות מי זהר", "bold": false, "kind": "ingredients"}, {"text": "3 כוסות מים", "bold": false, "kind": "ingredients"}, {"text": "לבשל על אש נמוכה עד להסמכה במשך רבע שעה.", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "בקערה גדולה לערבב הכל יחד במטרפה.", "bold": false, "kind": "method"}, {"text": "להניח בתבנית עגולה בקוטר 26.", "bold": false, "kind": "method"}, {"text": "לאפות בחום של 180 מעלות למשך 40 דקות.", "bold": false, "kind": "method"}, {"text": "לאחר שהעוגה נאפתה, נמזוג מעליה את הסירופ החם.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r15", "title": "סמבוסק בג'בן", "category": "מאפים", "blocks": [{"text": "כמות מנות: 20-25 יחידות", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "לבצק", "bold": true, "kind": "subheading"}, {"text": "1 ק\"ג קמח רגיל", "bold": false, "kind": "ingredients"}, {"text": "200 גרם מחמאה/מרגרינה", "bold": false, "kind": "ingredients"}, {"text": "½ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמרים", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "קורט מלח", "bold": false, "kind": "ingredients"}, {"text": "2 כוסות מים פושרים", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "קילו גבינת חמד מגורדת (מומלץ גבינה עיראקית ממחלבת עברי)", "bold": false, "kind": "ingredients"}, {"text": "200 גרם גבינה צהובה מגורדת", "bold": false, "kind": "ingredients"}, {"text": "2 ביצים", "bold": false, "kind": "ingredients"}, {"text": "2 כפות קמח", "bold": false, "kind": "ingredients"}, {"text": "קורט מלח", "bold": false, "kind": "ingredients"}, {"text": "למריחה על המאפה: 1 ביצה", "bold": true, "kind": "subheading"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "מנפים את הקמח בקערה עמוקה, מוסיפים לקמח את המצרכים היבשים ומערבבים יחד.", "bold": false, "kind": "method"}, {"text": "ממיסים במיקרוגל את המחמאה ומוסיפים לקערת הקמח. מוסיפים לקערה גם את השמן.", "bold": false, "kind": "method"}, {"text": "לאט לאט מוסיפים את המים הפושרים, יש ללוש את הבצק כעשר דקות לבצק אחיד.", "bold": false, "kind": "method"}, {"text": "מניחים להתפחה כשעה לאחר מכן לשים שוב ומניחים להתפחה שנייה כחצי שעה.", "bold": false, "kind": "method"}, {"text": "מערבבים בקערה את כל חומרי המילוי: גבינת חמד וצהובה מגורדות, 2 ביצים, 2 כפות קמח וקורט מלח.", "bold": false, "kind": "method"}, {"text": "מניחים את הבצק על השולחן קורצים עיגולים בגודל כדור פינג פונג פותחים כל עיגול.", "bold": false, "kind": "method"}, {"text": "ממלאים כל עיגול בכף גדושה של מילוי הגבינה וסוגרים בצורת סהרון.", "bold": false, "kind": "method"}, {"text": "מניחים על מגש מורחים בביצה.", "bold": false, "kind": "method"}, {"text": "אופים בחום של 200 מעלות למשך 20 דקות עד להשחמה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 20-25 יחידות", "image": "assets/album/dish-cheese-approved.jpg", "imageSource": "Word: image20", "photoStory": ["shoot-cheese-tray", "shoot-cheese-prep", "shoot-cheese-fold", "shoot-cheese-filling"]}, {"id": "r16", "title": "כעכעת", "category": "מאפים", "blocks": [{"text": "כמות מנות: 20-25", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 ק\"ג קמח רגיל", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמרים", "bold": false, "kind": "ingredients"}, {"text": "6 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "קורט מלח", "bold": false, "kind": "ingredients"}, {"text": "2 כפות חוויג' תבלין עיראקי לאפייה", "bold": false, "kind": "ingredients"}, {"text": "200 גרם חמאה / מחמאה רכה", "bold": false, "kind": "ingredients"}, {"text": "חצי כוס שמן קנולה", "bold": false, "kind": "ingredients"}, {"text": "2 כוסות מים פושרים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בקערה עמוקה לשים את הקמח וכל המצרכים היבשים, להוסיף את המרגרינה/חמאה המומסת והשמן, להוסיף את המים הפושרים וללוש יחד כעשר דקות.", "bold": false, "kind": "method"}, {"text": "לתת לבצק לתפוח כשעה עד להכפלתו.", "bold": false, "kind": "method"}, {"text": "מחלקים את הבצק לכדורים קטנים וצרים צמידים בגודל בינוני.", "bold": false, "kind": "method"}, {"text": "מניחים על מגש מורחים ביצה טרופה.", "bold": false, "kind": "method"}, {"text": "אופים בחום של 200 מעלות במשך 20 דקות עד להשחמה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 20-25", "image": "assets/album/shoot-kaakat.jpg", "imageSource": "Word: image21"}, {"id": "r17", "title": "בעבע בתמר", "category": "מאפים", "blocks": [{"text": "כמות מנות: 20-25", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "ק\"ג קמח רגיל", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמרים", "bold": false, "kind": "ingredients"}, {"text": "חוויג' תבלין עיראקי לאפייה.", "bold": false, "kind": "ingredients"}, {"text": "6 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "קורט מלח", "bold": false, "kind": "ingredients"}, {"text": "½ חבילה מרגרינה / מחמאה", "bold": false, "kind": "ingredients"}, {"text": "½ כוס שמן קנולה.", "bold": false, "kind": "ingredients"}, {"text": "2 כוסות מים פושרים.", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "חבילת תמרים בואקום", "bold": false, "kind": "ingredients"}, {"text": "5 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "½ כפית קינמון.", "bold": false, "kind": "ingredients"}, {"text": "למריחה על המאפה", "bold": true, "kind": "subheading"}, {"text": "ביצה טרופה", "bold": false, "kind": "ingredients"}, {"text": "שומשום", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לשים בקערה עמוקה את הקמח המנופה ושאר המצרכים היבשים, להוסיף את המרגרינה המומסת והשמן, להוסיף את המים הפושרים וללוש כעשר דקות.", "bold": false, "kind": "method"}, {"text": "להניח להתפחה עד שיכפיל את עצמו.", "bold": false, "kind": "method"}, {"text": "לחלק את הבצק לכדורים קטנים, לפתוח כל כדור ולמלא בכדור קטן מתערובת התמרים לסגור ולפתוח עם מערוך ליצירת עיגול.", "bold": false, "kind": "method"}, {"text": "להניח על מגש למרוח בביצה טרופה ולפזר שומשום לדקור עם מזלג כל עיגול בכדי שלא יתפחו.", "bold": false, "kind": "method"}, {"text": "לאפות בחום של 200 מעלות למשך 20 דקות עד להשחמה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 20-25", "image": "assets/album/shoot-date-cookies.jpg", "imageSource": "Word: image22"}, {"id": "r18", "title": "עוגת תפוחים", "category": "מאפים", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "לבלילה", "bold": true, "kind": "subheading"}, {"text": "¾ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "½ 1 כוסות קמח תופח", "bold": false, "kind": "ingredients"}, {"text": "¼ 1 סוכר", "bold": false, "kind": "ingredients"}, {"text": "3 כפות מים", "bold": false, "kind": "ingredients"}, {"text": "2 ביצים", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "5 תפוחים ירוקים קלופים וחתוכים לפרוסות.", "bold": false, "kind": "ingredients"}, {"text": "5 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 כף קינמון", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "בקערה גדולה מערבבים שמן, קמח, ¼ 1 כוסות סוכר,מים וביצים, עד לקבלת תערובת נוזלית ואחידה.", "bold": false, "kind": "method"}, {"text": "בקערה נפרדת, מערבבים את פלחי התפוחים, סוכר וקינמון.", "bold": false, "kind": "method"}, {"text": "משמנים תבנית פיירקס,שופכים שני שליש מהבצק, תוחבים את התפוחים לעיסת הבצק ואת הבצק הנותר שופכים מלמעלה.", "bold": false, "kind": "method"}, {"text": "אופים ב-180 מעלות כ-50 דק', עד להשחמה.", "bold": false, "kind": "method"}, {"text": "מומלץ להגיש עם קצפת.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r19", "title": "דג מרוקאי של שבת", "category": "דגים", "blocks": [{"text": "כמות מנות: 7", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "7 פרוסות דג טונה לבנה (או אדומה)", "bold": false, "kind": "ingredients"}, {"text": "10 שיני שום קלופים", "bold": false, "kind": "ingredients"}, {"text": "2 צרורות כוסברה חתוכה קלות", "bold": false, "kind": "ingredients"}, {"text": "2 גזרים קלופים וחתוכים לרבעים", "bold": false, "kind": "ingredients"}, {"text": "2 גמבות", "bold": false, "kind": "ingredients"}, {"text": "4 כפות פפריקה אדומה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "חצי כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית כרכום", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "משרים בקערה את פרוסות הדג במים וחומץ למשך שעה ולאחר מכן שוטפים.", "bold": false, "kind": "method"}, {"text": "בסיר גדול ורחב מניחים גזר, גמבה, שיני שום, מחצית מהכוסברה. מוסיפים לסיר את פרוסות הדג ומוסיפים מעל את יתר הכוסברה. זורים על הדגים מלח, פלפל, כורכום ומכסים את הדגים במי ברז (המים צריכים לכסות את הדגים בלבד), לאחר הבאה לרתיחה מנמיכים את הלהבה ומבשלים עד שנותרים מעט מהנוזלים. לאחר צמצום הנוזלים מערבבים בכוס פפריקה ושמן ושופכים מעל הדגים, ממשיכים בבישול עוד חמש דקות ומכבים את הגז.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 7"}, {"id": "r20", "title": "סלמון בתנור - בסגנון צרפתי", "category": "דגים", "blocks": [{"text": "כמות מנות: 6", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 קילו דג סלמון נקי מעצמות", "bold": false, "kind": "ingredients"}, {"text": "3 שיני שום קצוץ", "bold": false, "kind": "ingredients"}, {"text": "כף מיונז", "bold": false, "kind": "ingredients"}, {"text": "לימון חתוך לפרוסות (עיגולים) - לא חובה", "bold": false, "kind": "ingredients"}, {"text": "כף חרדל דיז'ון", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח גס", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "כוסברה חתוכה - לא חובה", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "מחממים מראש תנור על 180 מעלות.", "bold": false, "kind": "method"}, {"text": "על מגש מרופד בנייר אפייה מניחים פרוסות לימון או מפזרים מעט שמן זית. מניחים מעל את הדג. ניתן לשים נתח שלם או פרוסות. לבחירתכן.", "bold": false, "kind": "method"}, {"text": "בקערה מערבבים מיונז, חרדל, שום, כוסברה מלח ופלפל ומורחים היטב מעל הדג ובצידו.", "bold": false, "kind": "method"}, {"text": "מכסים את הדג בנייר אפייה ומכניסים את המגש לתנור המחומם, על 180 מעלות.", "bold": false, "kind": "method"}, {"text": "לאחר 10 דק' מוציאים את הנייר וממשיכים לצלות את הדג לעוד 5 דק' נוספות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 6"}, {"id": "r21", "title": "סלמון בתנור - בסגנון אסייתי", "category": "דגים", "blocks": [{"text": "כמות מנות: 6", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 קילו דג סלמון נקי מעצמות", "bold": false, "kind": "ingredients"}, {"text": "כף מיונז/שמן זית", "bold": false, "kind": "ingredients"}, {"text": "3 כפות סויה", "bold": false, "kind": "ingredients"}, {"text": "כף סילאן", "bold": false, "kind": "ingredients"}, {"text": "בצל ירוק קצוץ", "bold": false, "kind": "ingredients"}, {"text": "מלח גס", "bold": false, "kind": "ingredients"}, {"text": "פלפל שחור גרוס", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "מניחים את הדג על תבנית מרופדת בנייר אפייה, מערבבים את כל המרכיבים מלבד הבצל הירוק בקערית ושופכים על הדג. מוודאים שכולו מתובל ומפזרים מעליו את הבצל הירוק.", "bold": false, "kind": "method"}, {"text": "אופים בתנור למשך 15 דקות על 200 מעלות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 6"}, {"id": "r22", "title": "דניס בתנור", "category": "דגים", "blocks": [{"text": "כמות מנות: 2", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "2 דגי דניס", "bold": false, "kind": "ingredients"}, {"text": "6 שיני שום", "bold": false, "kind": "ingredients"}, {"text": "לימון טרי קלוף ללא הגרעינים", "bold": false, "kind": "ingredients"}, {"text": "פפריקה מתוקה שתי כפות", "bold": false, "kind": "ingredients"}, {"text": "2 כפיות מלח גס", "bold": false, "kind": "ingredients"}, {"text": "2 כפיות פלפל שחור גרוס", "bold": false, "kind": "ingredients"}, {"text": "שמן זית", "bold": false, "kind": "ingredients"}, {"text": "פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "להניח את הדג על קרש חיתוך, לעשות שלושה פסי חיתוך על הדג ולמלא אותו בתערובת: לימון חתוך לקוביות קטנות, פפריקה, שמן זית, מלח, פלפל, שום כתוש, פטרוזיליה קצוצה.", "bold": false, "kind": "method"}, {"text": "להניח על מגש ולאפות בחום של 200 מעלות למשך 25 דקות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 2"}, {"id": "r23", "title": "גפילטע פיש", "category": "דגים", "blocks": [{"text": "כמות קציצות: 25 קציצות", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 קג' דג קרפיון טחון (לשמור את הראש והאידרה לבישול)", "bold": false, "kind": "ingredients"}, {"text": "3 בצלים בינוניים", "bold": false, "kind": "ingredients"}, {"text": "2 ביצים", "bold": false, "kind": "ingredients"}, {"text": "2 כפות קמח מצה", "bold": false, "kind": "ingredients"}, {"text": "כפית וחצי מלח", "bold": false, "kind": "ingredients"}, {"text": "כפית וחצי פלפל שחור דק", "bold": false, "kind": "ingredients"}, {"text": "כפית סוכר", "bold": false, "kind": "ingredients"}, {"text": "2 גזר", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בסיר רחב ועמוק להניח את ראש הדג האידרה,את הגזר פורסים לעיגולים אחידים ופרוסות בצל,מוסיפים כפית וחצי מלח, כפית פלפל שחור כף סוכר ממלאים את הסיר במי ברז כ - ¾ סיר.", "bold": false, "kind": "method"}, {"text": "בקערה:", "bold": false, "kind": "method"}, {"text": "שמים את הדג הטחון עם 2 הביצים 2 כפות קמח מצה 2 בצלים מגורדים דק וסחוטים, כפית וחצי מלח כפית וחצי פלפל כפית סוכר, לערבב הכל יחד היטב וליצור קציצות שטוחות.", "bold": false, "kind": "method"}, {"text": "כשהמים בסיר רתחו אנו מניחים את הקציצות בתוך הסיר מסדרים אותן כך שלא ידבקו זו בזו.", "bold": false, "kind": "method"}, {"text": "לבשל על להבה נמוכה כ- שעה וחצי.", "bold": false, "kind": "method"}, {"text": "לאחר שהם התבשלו והצתננו יש לסדר את הקציצות להניח מעל כל קציצה פרוסת גזר מבושל ולקחת מן הציר ולשפוך ולקרר לפחות יום במקרר בכדי שיווצר מעין ג'לי.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות קציצות: 25 קציצות"}, {"id": "r24", "title": "סלונה", "category": "דגים", "blocks": [{"text": "סלונה מכינים בחגים, אמא היתה מכינה בסוכות", "bold": false, "kind": "intro"}, {"text": "מנות: 6-8", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "500 גר' דגים פילה מלרוזה", "bold": false, "kind": "ingredients"}, {"text": "6 עגבניות פרוסות", "bold": false, "kind": "ingredients"}, {"text": "4 בצלים גדולים פרוסים", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פפריקה אדומה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "¼ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "קמח לקימוח הדגים", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "שמן לטיגון", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "מניחים את הפילה בקערה עם מים ומעט חומץ משרים חצי שעה לאחר מכן שוטפים את הדגים וסוחטים אותם.", "bold": false, "kind": "method"}, {"text": "במחבת שמים שמן לטיגון הדגים (לא שמן עמוק),", "bold": false, "kind": "method"}, {"text": "בצלחת מניחים קמח, את הדגים מתבלים במלח פלפל שחור כורכום ומקמחים משני צידי הדג,מטגנים עד להשחמה קלה.", "bold": false, "kind": "method"}, {"text": "לאחר מכן מסדרים בסיר שטוח ורחב פרוסות של בצלים, פרוסות של עגבניות ומעל את הדגים,וכך הלאה לחזור כמה שכבות,השכבה העליונה תהיה עגבניות.", "bold": false, "kind": "method"}, {"text": "להכין רוטב בקערה, ½ כוס מים ½ כפית מלח, פפריקה, סוכר, לימון לצקת לסיר ולכסות במכסה.", "bold": false, "kind": "method"}, {"text": "לבשל על אש נמוכה כ-45-60 דקות.", "bold": false, "kind": "method"}, {"text": "להגיש חם.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "מנות: 6-8"}, {"id": "r25", "title": "קציצות דגים", "category": "דגים", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "לקציצות", "bold": true, "kind": "subheading"}, {"text": "½ קילו דג טונה טחון", "bold": false, "kind": "ingredients"}, {"text": "½ קילו דג סול טחון", "bold": false, "kind": "ingredients"}, {"text": "7-8 שיני שום קלופים", "bold": false, "kind": "ingredients"}, {"text": "4 כפות קמח מצה", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "כף כמון", "bold": false, "kind": "ingredients"}, {"text": "3 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "לרוטב", "bold": true, "kind": "subheading"}, {"text": "¼ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "פפריקה, מלח", "bold": false, "kind": "ingredients"}, {"text": "2 גמבות חתוכות לקוביות", "bold": false, "kind": "ingredients"}, {"text": "2 שיני שום", "bold": false, "kind": "ingredients"}, {"text": "פלפל חריף", "bold": false, "kind": "ingredients"}, {"text": "6 עגבניות קלופות ומרוסקות", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "בסיר רחב נחמם את השמן נשים את הגמבות,העגבניות,השום, פלפל החריף והתבלינים", "bold": false, "kind": "method"}, {"text": "נטגן מעט ונוסיף שתי כוסות מים ונרתיח.", "bold": false, "kind": "method"}, {"text": "קציצות:", "bold": true, "kind": "subheading"}, {"text": "נשרה את הדגים בחומץ חצי שעה, נשטוף ונסחוט אותם, נכניס למג'ימיקס נטחן יחד עם עם כל חומרי תערובת הקציצות.", "bold": false, "kind": "method"}, {"text": "נגלגל לקציצות בגודל כדור פינג פונג, ונזרוק אל תוך הסיר, נבשל על להבה נמוכה כ-¼ שעה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "", "image": "assets/r25.jpg", "imageSource": "Word: image23"}, {"id": "r26", "title": "פטה כבד עם ריבת בצל", "category": "מנות פתיחה", "blocks": [{"text": "כמות מגשים: מגש אינגליש קייק אחד", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "לפטה כבד", "bold": true, "kind": "subheading"}, {"text": "10 כבד עוף", "bold": false, "kind": "ingredients"}, {"text": "3 בצלים לטיגון", "bold": false, "kind": "ingredients"}, {"text": "שמן קנולה", "bold": false, "kind": "ingredients"}, {"text": "4 ביצים קשות", "bold": false, "kind": "ingredients"}, {"text": "מלח ופלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "לריבת הבצל", "bold": true, "kind": "subheading"}, {"text": "5 בצלים סגולים", "bold": false, "kind": "ingredients"}, {"text": "4 כפות שמן קנולה", "bold": false, "kind": "ingredients"}, {"text": "1 כוס סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 כוס יין אדום מתוק", "bold": false, "kind": "ingredients"}, {"text": "4 כפות חומץ בלסמי", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "כבד קצוץ:", "bold": true, "kind": "subheading"}, {"text": "מטגנים את הבצל והכבד עם מלח ופלפל, לאחר הטיגון נעביר את הכבד (כולל הנוזלים שבמחבת) למעבד מזון, נוסיף את הביצים הקשות ונטחן עד לקבלת המרקם הרצוי.", "bold": false, "kind": "method"}, {"text": "ריבת בצל:", "bold": true, "kind": "subheading"}, {"text": "מחממים את השמן במחבת עמוקה, מוסיפים את הבצל הפרוס לרצועות דקות מטגנים מעט מוסיפים את הסוכר מערבבים, מוסיפים את היין וחומץ הבלסמי, מבשלים על להבה נמוכה בערך 45 דקות עד צימצום כל הנוזלים מערבבים מידי פעם עם כף עץ.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מגשים: מגש אינגליש קייק אחד", "processImage": "assets/album/family-14.jpg", "processCaption": "דינה מכינה ריבת בצל", "image": "assets/album/family-16.jpg"}, {"id": "r27", "title": "סלט כרוב אסייאתי", "category": "מנות פתיחה", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "כרוב ראש אחד", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס שמן רגיל", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס סויה", "bold": false, "kind": "ingredients"}, {"text": "3 כפות סילאן", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס חומץ", "bold": false, "kind": "ingredients"}, {"text": "¼ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "שומשום/פקאן/שקדים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לקצוץ דק את הכרוב.", "bold": false, "kind": "method"}, {"text": "במחבת שמים שמן, סויה, סילאן, חומץ, מלח ופלפל שחור. מבשלים עד כדי מעט צמצום ושופכים חם על הכרוב.", "bold": false, "kind": "method"}, {"text": "קולים שומשום בנפרד ומוסיפים לסלט. מערבבים.", "bold": false, "kind": "method"}, {"text": "במקום שומשום ניתן להשתמש בפקאן סיני או שקדים קלופים קצוצים.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r28", "title": "צ'ירשי - תבשיל דלעת", "category": "מנות פתיחה", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "חצי קילו דלעת", "bold": false, "kind": "ingredients"}, {"text": "10 שיני שום", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "כפית כמון", "bold": false, "kind": "ingredients"}, {"text": "2 כפות פפריקה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "להניח בתוך הסיר את הדלעת הקלופה וחתוכה לקוביות, להוסיף את השום הכתוש,להוסיף מי ברז עד לכיסוי הדלעת לבשל עד לריכוך וצימצום הנוזלים,להוסיף את התבלינים והשמן למעוך עם מועך, לבשל עוד חמש דקות ולכבות את הגז.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r29", "title": "פלפל ממולא", "category": "ממולאים", "blocks": [{"text": "כמות מנות: 6", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "פלפל גמבה", "bold": false, "kind": "ingredients"}, {"text": "כוס אורז עגול", "bold": false, "kind": "ingredients"}, {"text": "צרור שמיר", "bold": false, "kind": "ingredients"}, {"text": "2 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "¼ ק\"ג בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "2 קופסאות קטנות רסק עגבניות", "bold": false, "kind": "ingredients"}, {"text": "רוטב רימונים (חצי כוס)", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "½ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בקערה גדולה להניח את הבשר הטחון את האורז השטוף שמיר קצוץ, בצל אחד קצוץ,רסק עגבניות אחד,רבע כוס רוטב רימונים,מלח פלפל,¼ כוס שמן לערבב היטב הכל יחד.", "bold": false, "kind": "method"}, {"text": "את הגמבות לשטוף לחצות את מכסה הפלפל לא עד הסוף לנקות ולמלא במילוי של הבשר.", "bold": false, "kind": "method"}, {"text": "להניח בסיר כך שהפלפלים יסודרו עם המכסה שלהם כלפי מעלה.", "bold": false, "kind": "method"}, {"text": "לרוטב:", "bold": false, "kind": "method"}, {"text": "בקערה גדולה להוסיף 1 רסק עגבניות מיץ מחצי לימון את שאר רוטב הרימונים 2 כפות סוכר,מעט מלח פלפל שחור מעט שמן לערבב יחד להוסיף מי ברז לשפוך את תוך הסיר עד לכיסוי הפלפלים.", "bold": false, "kind": "method"}, {"text": "לבשל עד לצמצום הנוזלים על להבה בינונית.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: כמה פלפלים מכינים, והאם משתמשים בלימון שלם או בחצי?"], "servings": "כמות מנות: 6", "image": "assets/r29.jpg", "imageSource": "Word: image25"}, {"id": "r30", "title": "עלי מנגולד ממולאים", "category": "ממולאים", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "לעלים", "bold": true, "kind": "subheading"}, {"text": "20 עלי מנגולד (2 חבילות מנגולד)", "bold": false, "kind": "ingredients"}, {"text": "2 בצלים קצוצים", "bold": false, "kind": "ingredients"}, {"text": "1 כוס אורז שטוף ומסונן", "bold": false, "kind": "ingredients"}, {"text": "¼ קילו בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "½ כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס רכז רימונים", "bold": false, "kind": "ingredients"}, {"text": "לרוטב", "bold": true, "kind": "subheading"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "1 כף סוכר", "bold": false, "kind": "ingredients"}, {"text": "100 גרם רסק עגבניות (קופסא קטנה)", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "3 כוסות מים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לשטוף היטב את עלי המנגולד, לחתוך את הקצה הלבן של העלה ולשמור אותו בצד", "bold": false, "kind": "method"}, {"text": "להניח את העלים הירוקים בקערה עם מים רותחים עד לריכוך ולסנן בעדינות פן יקרעו", "bold": false, "kind": "method"}, {"text": "את חומרי המילוי נערבב בקערה גדולה", "bold": false, "kind": "method"}, {"text": "את העלים נניח על משטח עבודה, לפתוח את העלה בעדינות ולמלא במילוי", "bold": false, "kind": "method"}, {"text": "בסיר רחב נניח בתחתית את העלים הלבנים ופרוסות בצל מעל נניח את העלים הממולאים", "bold": false, "kind": "method"}, {"text": "ונשפוך את הרוטב מעל הממולאים,", "bold": false, "kind": "method"}, {"text": "נבשל על להבה בינונית במשך 20-25 דק'.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r31", "title": "סלק ממולא", "category": "ממולאים", "blocks": [{"text": "כמות מנות: 5", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "4 ראשי סלק אדום", "bold": false, "kind": "ingredients"}, {"text": "200 גר' בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס אורז", "bold": false, "kind": "ingredients"}, {"text": "1 בצל קצוץ", "bold": false, "kind": "ingredients"}, {"text": "10 גבעולי פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "מלח, פלפל", "bold": false, "kind": "ingredients"}, {"text": "½ כוס רוטב רימונים", "bold": false, "kind": "ingredients"}, {"text": "3 כפות סילן", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס שמן זית", "bold": false, "kind": "ingredients"}, {"text": "לרוטב:", "bold": true, "kind": "subheading"}, {"text": "1 לימון", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "2 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "2 כוסות מים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "נקלף את הסלקים נוציא את התוכן של הסלק נחתוך לקוביות קטנות מניחים בקערה", "bold": false, "kind": "method"}, {"text": "מוסיפים את הבשר האורז ואת שאר מצרכי המילוי,מערבבים יחד היטב.", "bold": false, "kind": "method"}, {"text": "מניחים את הסלקים הממולאים בסיר בינוני,מוסיפים מעל את הרוטב.", "bold": false, "kind": "method"}, {"text": "מבשלים על להבה בינונית במשך כשעה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: האם התפוקה 4 או 5 מנות? כיצד ממלאים ומתי מוסיפים את המילוי לסלקים?"], "servings": "כמות מנות: 5", "image": "assets/r31.jpg", "imageSource": "Word: image27"}, {"id": "r32", "title": "עלי גפן ממולאים", "category": "ממולאים", "blocks": [{"text": "כמות מנות: 40 עלים", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "עלי גפן", "bold": false, "kind": "ingredients"}, {"text": "למילוי:", "bold": true, "kind": "subheading"}, {"text": "1 כוס אורז עגול", "bold": false, "kind": "ingredients"}, {"text": "צרור עלי שמיר", "bold": false, "kind": "ingredients"}, {"text": "250 גר בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "3 בצלים קצוצים", "bold": false, "kind": "ingredients"}, {"text": "1 ½ כפיות מלח דק", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "4 כפות שמן זית", "bold": false, "kind": "ingredients"}, {"text": "2 עגבניות קלופות וקצוצות דק", "bold": false, "kind": "ingredients"}, {"text": "לערבב את כל המצרכים יחד", "bold": false, "kind": "ingredients"}, {"text": "לרוטב:", "bold": true, "kind": "subheading"}, {"text": "1 ½ לימונים סחוטים", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "3 כוסות מים", "bold": false, "kind": "ingredients"}, {"text": "2 עגבניות קלופות ופרוסות", "bold": false, "kind": "ingredients"}, {"text": "מעט שמן זית לזילוף", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לשטוף את העלים במיי ברז לסנן,", "bold": false, "kind": "method"}, {"text": "לשים בקערה את העלים במים רותחים לשלוק אותם להוציא ולסנן.", "bold": false, "kind": "method"}, {"text": "לאחר מכן נשטח כל עלה ונמלא בתערובת הבשר והאורז הגלגל היטב.", "bold": false, "kind": "method"}, {"text": "בסיר עגול ורחב נניח שני בצלים פרוסים לפרוסות עגולות,מעליהן נניח את עלי הגפן המגולגלים בצורה מעגלית בתחתית הסיר.", "bold": false, "kind": "method"}, {"text": "וכך נמשיך להניח גם את שאר העלים המגולגלים מלמעלה.", "bold": false, "kind": "method"}, {"text": "מעל כולם נפזר את העגבניות הפרוסות.", "bold": false, "kind": "method"}, {"text": "הרוטב:", "bold": true, "kind": "subheading"}, {"text": "נשפוך את הרוטב מעל הכל, נזלוף מעט שמן זית, נבשל במשך 90 דקות על להבה נמוכה.", "bold": false, "kind": "method"}, {"text": "בתאבון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 40 עלים", "image": "assets/r32.jpg", "imageSource": "Word: image29"}, {"id": "r33", "title": "כרוב ממולא", "category": "ממולאים", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 ראש כרוב גדול", "bold": false, "kind": "ingredients"}, {"text": "למילוי", "bold": true, "kind": "subheading"}, {"text": "½ קילו בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "½ כוס אורז שטוף ומסונן עדיף אורז עגול", "bold": false, "kind": "ingredients"}, {"text": "1 בצל קצוץ - רצוי לטגן מראש", "bold": false, "kind": "ingredients"}, {"text": "חצי צרור שמיר", "bold": false, "kind": "ingredients"}, {"text": "½1 כפיות מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל שחור טחון", "bold": false, "kind": "ingredients"}, {"text": "½ כפית בהרט", "bold": false, "kind": "ingredients"}, {"text": "3 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "1 קופסה קטנה רסק עגבניות", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "הכנת תערובת המילוי", "bold": true, "kind": "subheading"}, {"text": "שמים את הבשר חצי קילו", "bold": false, "kind": "method"}, {"text": "1 בצל קצוץ אפשר לטגן ואז להוסיף לקערת התערובת", "bold": false, "kind": "method"}, {"text": "חופן שמיר מכובד קצוץ", "bold": false, "kind": "method"}, {"text": "מלח", "bold": false, "kind": "method"}, {"text": "פלפל שחור טחון", "bold": false, "kind": "method"}, {"text": "1/2 כפית בהרט", "bold": false, "kind": "method"}, {"text": "פפריקה אדומה כפית", "bold": false, "kind": "method"}, {"text": "שלוש כפות שמן", "bold": false, "kind": "method"}, {"text": "1 קופסא רסק עגבניות", "bold": false, "kind": "method"}, {"text": "לערבב הכל יחד.", "bold": false, "kind": "method"}, {"text": "עלי הכרוב:", "bold": false, "kind": "method"}, {"text": "להניח על קרש חיתוך עלה אפשר לחצות אותו לאורך כך שמכל עלה גדול יהיו שניים ואז לגלגל כמו עלי גפן.", "bold": false, "kind": "method"}, {"text": "בסיר:", "bold": false, "kind": "method"}, {"text": "להניח שני בצלים בתחתית הסיר לפרוס אותם לעיגולים.", "bold": false, "kind": "method"}, {"text": "אחרי להניח את עלי הכרוב בסיר כך שיהיו מסודרים באופן מעגלי.", "bold": false, "kind": "method"}, {"text": "לרוטב:", "bold": false, "kind": "method"}, {"text": "בקערה לשים 2 רסק עגבניות", "bold": false, "kind": "method"}, {"text": "מיץ מלימון אחד", "bold": false, "kind": "method"}, {"text": "3 כפות סוכר", "bold": false, "kind": "method"}, {"text": "מלח", "bold": false, "kind": "method"}, {"text": "פלפל", "bold": false, "kind": "method"}, {"text": "ומעט שמן", "bold": false, "kind": "method"}, {"text": "מי ברז בערך שתי כוסות כך שיכסה את הכרוב.", "bold": false, "kind": "method"}, {"text": "לבשל עד שיצטמצמו הנוזלים,רצוי לבשל על להבה בינונית.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: מתי מערבבים את האורז במילוי, ומה הכמות הכוללת של רסק העגבניות לרוטב?"], "servings": ""}, {"id": "r34", "title": "אסאדו בתנור", "category": "בשר", "blocks": [{"text": "כמות מנות: 6", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "2 ק\"ג אסאדו עם עצם, מחולק לנתחים (בדרך כלל מאורכים)", "bold": false, "kind": "ingredients"}, {"text": "3 גזרים בינוניים, קלופים וחתוכים למקטעים", "bold": false, "kind": "ingredients"}, {"text": "2 כרישות גדולות, חתוכות למקטעים", "bold": false, "kind": "ingredients"}, {"text": "3 גבעולי טימין טרי (אם אין, אז טימין יבש. לא צריך להיות כבדים!)", "bold": false, "kind": "ingredients"}, {"text": "2 ראשי שום", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח גס", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פלפל גרוס", "bold": false, "kind": "ingredients"}, {"text": "4 כפות שמן זית", "bold": false, "kind": "ingredients"}, {"text": "1 כף חרדל דיז'ון גרגירים", "bold": false, "kind": "ingredients"}, {"text": "2 כף סילאן/דבש", "bold": false, "kind": "ingredients"}, {"text": "2 כף סויה", "bold": false, "kind": "ingredients"}, {"text": "2 כוסות יין יבש (לבן/אדום)", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בקערה גדולה מניחים את הבשר, מתבלים אותו במלח, פלפל, חרדל, סילאן/דבש וסויה. עושים לו עיסוי קל על מנת שהתיבול יהיה אחיד.", "bold": false, "kind": "method"}, {"text": "מעבירים את נתחי הבשר לתבנית עמוקה (מכיוון שבהמשך יווצרו נוזלים), לצידו מניחים את ירקות השורש ואת שני ראשי השום. שופכים את שארית התיבול שנשארה בקערה על פני הירקות. שופכים מעל הכל את היין וניתן לפזר שוב עוד קצת מלח גס. מוסיפים את הטימין מעל.", "bold": false, "kind": "method"}, {"text": "מחממים את התנור ל־250 מעלות, מכסים את התבנית בנייר אלומיניום ומכניסים לתנור ל־45 דקות בחום של 250 מעלות. לאחר מכן מנמיכים ל130-150 מעלות למשך 3-4 שעות (לבדוק לאחר 3 שעות את מצבו ולהחליט בהתאם האם הבשר זקוק לעוד חצי שעה או שעה).", "bold": false, "kind": "method"}, {"text": "לסיום, לחובבי הקצוות השרופים, ניתן לחשוף את הבשר לחום למשך רבע שעה על 180 מעלות.", "bold": false, "kind": "method"}, {"text": "טיפ של צאלה: להוסיף תפוז סחוט", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 6", "image": "assets/album/family-01.jpg", "imageSource": "photo-selection 01, identified as asado"}, {"id": "r35", "title": "בשר צלי", "category": "בשר", "blocks": [{"text": "כמות מנות: 10 פרוסות", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "בשר צלי כתף מס' 5 טרי קילו וחצי", "bold": false, "kind": "ingredients"}, {"text": "1 בצל גדול", "bold": false, "kind": "ingredients"}, {"text": "5 גבעולים סלרי", "bold": false, "kind": "ingredients"}, {"text": "10 עלי כרפס", "bold": false, "kind": "ingredients"}, {"text": "10 פטריות פורטובלו", "bold": false, "kind": "ingredients"}, {"text": "5 שיני שום שלמים", "bold": false, "kind": "ingredients"}, {"text": "כוס וחצי יין אדום יבש", "bold": false, "kind": "ingredients"}, {"text": "מעט שמן לטיגון", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל שחור גרוס", "bold": false, "kind": "ingredients"}, {"text": "מעט כורכום", "bold": false, "kind": "ingredients"}, {"text": "3 כפות סילאן", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בסיר רחב נטגן את הבצל הקצוץ, נניח את הבשר נסגור אותו משני הצדדים, נוסיף פלפל, כורכום, שום, נמלא מי ברז עד מעל הבשר ונבשל עד לריכוך במשך שעתיים וחצי, לאחר מכן נוציא את הבשר נפרוס אותו נחזיר לסיר ונוסיף מלח, יין, סילאן סלרי, עלי כרפס פטריות ונבשל עוד חצי שעה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 10 פרוסות"}, {"id": "r36", "title": "במיה עם קוביות בשר", "category": "בשר", "blocks": [{"text": "כמות מנות:", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 ק\"ג בשר גולש", "bold": false, "kind": "ingredients"}, {"text": "1 ק\"ג במיה (אפשר קפואה)", "bold": false, "kind": "ingredients"}, {"text": "1 בצל קצוץ", "bold": false, "kind": "ingredients"}, {"text": "3 כפות שמן", "bold": false, "kind": "ingredients"}, {"text": "100 גרם רסק עגבניות", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "1 כף סוכר", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "4-5 כוסות מים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בסיר לחמם את השמן ולהוסיף את הבצל הקצוץ ולהשחים,", "bold": false, "kind": "method"}, {"text": "להוסיף את הבשר החתוך לקוביות להוסיף את הפלפל והמלח המים ולבשל את הבשר כשעה עד לריכוך.", "bold": false, "kind": "method"}, {"text": "לאחר מכן להוסיף את הרסק עגבניות, במיה, סוכר, לימון.", "bold": false, "kind": "method"}, {"text": "להמשיך לבשל על להבה נמוכה עוד 20 דקות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r37", "title": "דלעת עם קוביות בשר", "category": "בשר", "blocks": [{"text": "כמות מנות:", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 ק\"ג בשר גולש", "bold": false, "kind": "ingredients"}, {"text": "½ ק\"ג דלעת (חתוכה לקוביות)", "bold": false, "kind": "ingredients"}, {"text": "1 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "100 גר' רסק עגבניות", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סוכר", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "¼ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "1 לימון סחוט", "bold": false, "kind": "ingredients"}, {"text": "10 גבעולי נענע", "bold": false, "kind": "ingredients"}, {"text": "5-6 כוסות מים.", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בסיר נטגן את הבצל עד להשחמה,נוסיף את בשר הגולש החתוך לקוביות", "bold": false, "kind": "method"}, {"text": "את המלח, פלפל וכורכום, נוסיף את כוסות המים ונבשל כשעה עד לריכוך הבשר.", "bold": false, "kind": "method"}, {"text": "נוסיף לסיר את רסק העגבניות סוכר,לימון סחוט עלי נענע וקוביות הדלעת,", "bold": false, "kind": "method"}, {"text": "נמשיך לבשל עוד כעשרים דק' נוספות.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r38", "title": "לחמעג'ון", "category": "בשר", "blocks": [{"text": "מנות: 10-12", "bold": false, "kind": "yield"}, {"text": "מצרכים:", "bold": false, "kind": "section"}, {"text": "לבצק:", "bold": false, "kind": "ingredients"}, {"text": "3 כוסות קמח", "bold": false, "kind": "ingredients"}, {"text": "1 כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "½ כף סוכר", "bold": false, "kind": "ingredients"}, {"text": "2 כפיות שמרים", "bold": false, "kind": "ingredients"}, {"text": "⅓ כוס שמן זית 1 כוס מים פושרים.", "bold": false, "kind": "ingredients"}, {"text": "למילוי:", "bold": false, "kind": "ingredients"}, {"text": "1 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "300 גר' בשר טחון", "bold": false, "kind": "ingredients"}, {"text": "2 עגבניות קצוצות מקולפות", "bold": false, "kind": "ingredients"}, {"text": "כמון", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל", "bold": false, "kind": "ingredients"}, {"text": "צנוברים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנת הבצק:", "bold": false, "kind": "section"}, {"text": "בקערה גדולה נשים את הקמח נוסיף את הסוכר, שמרים מלח,שמן זית והמים ונלוש היטב", "bold": false, "kind": "method"}, {"text": "עד לקבלת בצק רך ונעים.", "bold": false, "kind": "method"}, {"text": "נניח את הבצק להתפחה של כ-½ שעה.", "bold": false, "kind": "method"}, {"text": "המילוי:", "bold": false, "kind": "method"}, {"text": "בסיר מטגנים את הבצל עד להשחמה,מוסיפים את הבשר התבלינים ומטגנים עד לשינוי צבעו של הבשר מוסיפים", "bold": false, "kind": "method"}, {"text": "את העגבניות הקצוצות ולהמשיך לבשל עד לצמצום הנוזלים.", "bold": false, "kind": "method"}, {"text": "אופן ההכנה:", "bold": false, "kind": "section"}, {"text": "לחלק את הבצק לכדורים, לרדד כל כדור במערוך לעיגול דק,לפזר על כל עיגול מהבשר(כשהוא קר),נפזר על כל עיגול צנוברים.", "bold": false, "kind": "method"}, {"text": "נסדר על תבנית מרופדת בנייר פרגמנט.", "bold": false, "kind": "method"}, {"text": "נאפה בחום של 200 מעלות במשך כ-20 דק'.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "מנות: 10-12"}, {"id": "r39", "title": "צוואר כבש", "category": "בשר", "blocks": [{"text": "מצרכים:", "bold": false, "kind": "section"}, {"text": "1בצל חתוך לקוביות", "bold": false, "kind": "ingredients"}, {"text": "8 שיני שום", "bold": false, "kind": "ingredients"}, {"text": "2 גמבות חתוכות לרצועות", "bold": false, "kind": "ingredients"}, {"text": "2 פלפל חריף יבש", "bold": false, "kind": "ingredients"}, {"text": "1.פלפל צילי חתוך לטבעות", "bold": false, "kind": "ingredients"}, {"text": "1 עגבניה", "bold": false, "kind": "ingredients"}, {"text": "1.ק\"ג בשר צוואר כבש פרוס לפרוסות", "bold": false, "kind": "ingredients"}, {"text": "1,כוס חומוס סנפרוסט", "bold": false, "kind": "ingredients"}, {"text": "כף פפריקה מתוקה בשמן", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": true, "kind": "section"}, {"text": "מחממים את השמן בסיר ומטגנים את הבצל ושיני השום עד שהבצל מזהיב.", "bold": false, "kind": "method"}, {"text": "מוסיפים את קוביות העגבניות פלפל הצילי ומבשלים כמה דקות.", "bold": false, "kind": "method"}, {"text": "מוסיפים את פרוסות צוואר הכבש וגרגירי החומוס מוסיפים מים עד לכיסוי כל הבשר.", "bold": false, "kind": "method"}, {"text": "מוסיפים את שני סוגי הפפריקה הצילי הפלפל היבש ומלח לפי הטעם,", "bold": false, "kind": "method"}, {"text": "מערבבים ומביאים לרתיחה.", "bold": false, "kind": "method"}, {"text": "מבשלים על להבה נמוכה עד שהבשר והחומוס רכים, כשעה.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: כף אחת או שתי כפות פפריקה? כמה גמבה ושמן?"], "servings": ""}, {"id": "r40", "title": "חמין מרוקאי", "category": "בשר", "blocks": [{"text": "מצרכים:", "bold": false, "kind": "section"}, {"text": "1 קילו בשר שריר מס' 8", "bold": false, "kind": "ingredients"}, {"text": "1 כוס גרגרי חומוס יבשים (ניתן להשרות לילה קודם)", "bold": false, "kind": "ingredients"}, {"text": "1 כוס שעועית לבנה יבשה (יש להשרות לילה קודם)", "bold": false, "kind": "ingredients"}, {"text": "1 כוס חיטה שטופה ומסוננת", "bold": false, "kind": "ingredients"}, {"text": "2 ראשי שום שלמים", "bold": false, "kind": "ingredients"}, {"text": "5 תפוחי אדמה בינוניים קלופים", "bold": false, "kind": "ingredients"}, {"text": "1 בטטה קלופה", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל", "bold": false, "kind": "ingredients"}, {"text": "פפריקה אדומה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "סילאן", "bold": false, "kind": "ingredients"}, {"text": "שמן", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": false, "kind": "section"}, {"text": "בסיר רחב מניחים את הקטניות, מלבד החיטה, מעל מניחים את הבשר, תפוחי האדמה, בטטה, ראשי השום, בשקית קוקי נשים את החיטה, נוסיף מלח, פלפל, פפריקה, ⅓ כוס שמן, 6 שיני שום, 2 כוסות סילאן ו-2 כוסות מים. נסגור את שקית הקוקי. נוסיף מים לסיר עד לכיסוי, נניח את שקית הקוקי מעל. נניח את הסיר על הגז, נביא לרתיחה ונכסה עם מכסה, נבשל כשעה. נכבה את הגז ונעביר לתנור שחומם מראש ל-130 מעלות למשך לילה שלם. אפשר להוסיף להוסיף ביצים שבושלו קודם לכן ולהוסיף לסיר לפני שמעבירים לתנור.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: בהכנת שקית החיטה כתוב 2 כוסות סילאן. האם הכוונה לכוסות או לכפות?"], "servings": ""}, {"id": "r41", "title": "עוף ממולא", "category": "עוף", "blocks": [{"text": "כמות מנות: 4", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "עוף שלם במשקל 1 ½ קילו", "bold": false, "kind": "ingredients"}, {"text": "½ כוס אורז בסמטי", "bold": false, "kind": "ingredients"}, {"text": "1 בצל", "bold": false, "kind": "ingredients"}, {"text": "חופן פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס צנוברים", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "בהרט", "bold": false, "kind": "ingredients"}, {"text": "פפריקה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "שמן קנולה", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לנקות ולשטוף את העוף השלם,בקערה נשים את האורז השטוף והמסונן,את הצנוברים הפטרוזיליה הקצוצה דק את הבצל הקצוץ והתבלינים לערבב הכל יחד ולמלא.", "bold": false, "kind": "method"}, {"text": "בקערה :", "bold": false, "kind": "method"}, {"text": "נשים 2 כפות פפריקה מתוקה מעט מלח גס בהרט ושני שיני שום כתושים שמן זית לערבב יחד ולמרוח את העוף מכל צדדי.", "bold": false, "kind": "method"}, {"text": "להניח במגש ונכסה עם נייר אלומיניום נכניס לתנור בחום של 200 מעלות למשך שעה, אחרי שעה להוריד את הנייר אלומיניום וניתן לו צריבה של עוד רבע שעה.", "bold": false, "kind": "method"}, {"text": "בתאבון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 4"}, {"id": "r42", "title": "טבית", "category": "עוף", "blocks": [{"text": "את הטבית אוכלים ביום שבת", "bold": false, "kind": "intro"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "3 כוסות אורז בסמטי", "bold": false, "kind": "ingredients"}, {"text": "עוף שלם", "bold": false, "kind": "ingredients"}, {"text": "5 יח ' קורקבנים", "bold": false, "kind": "ingredients"}, {"text": "2 בצלים גדולים", "bold": false, "kind": "ingredients"}, {"text": "5 גבעולי פטרוזיליה", "bold": false, "kind": "ingredients"}, {"text": "1 עגבניה", "bold": false, "kind": "ingredients"}, {"text": "1 קופסאות רסק עגבניות (100גר').", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס צנוברים", "bold": false, "kind": "ingredients"}, {"text": "4 כפיות מלח", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "2 כפות בהרט של טבית", "bold": false, "kind": "ingredients"}, {"text": "1 כפית פפריקה אדומה", "bold": false, "kind": "ingredients"}, {"text": "½ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "3 יח' הל שלם (למי שאוהב).", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בקערה מכניסים את חומרי המילוי לעוף:", "bold": false, "kind": "method"}, {"text": "חצי כוס אורז שטוף ומסונן", "bold": false, "kind": "method"}, {"text": "¼ כוס שמן קנולה", "bold": false, "kind": "method"}, {"text": "1בצל קצוץ דק", "bold": false, "kind": "method"}, {"text": "5 קורקבנים חתוכים קטן לקוביות(אפשר גם לחצאים).", "bold": false, "kind": "method"}, {"text": "1 עגבניה קלופה וחתוכה לקוביות", "bold": false, "kind": "method"}, {"text": "5 גבעולים פטרוזיליה קצוצה", "bold": false, "kind": "method"}, {"text": "1 כפית מלח", "bold": false, "kind": "method"}, {"text": "1 כפית פלפל שחור", "bold": false, "kind": "method"}, {"text": "כפית בהרט", "bold": false, "kind": "method"}, {"text": "לערבב יחד.", "bold": false, "kind": "method"}, {"text": "בסיר רחב ועמוק:", "bold": false, "kind": "method"}, {"text": "מטגנים 1 בצל עד להזהבה, מניחים את העוף הממולא מטגנים מעט משני הצדדים.", "bold": false, "kind": "method"}, {"text": "מוסיפים את רסק העגבניות התבלינים ומים עד לכיסוי העוף מרתיחים, לאחר שהנוזלים הגיעו לרתיחה מוסיפים את האורז 3 כוסות אורז שטוף.", "bold": false, "kind": "method"}, {"text": "מבשלים על להבה בינונית עד שהנוזלים מצטמצמים.", "bold": false, "kind": "method"}, {"text": "מכבים את הגז, מכניסים את הסיר לתנור ומבשלים ב- 150 מעלות.", "bold": false, "kind": "method"}, {"text": "אני מכניסה את הסיר לתנור מהשעה 22:00- ועד למחרת בשעה 12:00 בצהריים בודקת שלא ישרף, אפשר להוריד את המעלות ל- 120 מעלות אם רואים שזה מתייבש.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: האם יש 3 כוסות אורז בסך הכול או 3½? מתי מוסיפים את הצנוברים?"], "servings": ""}, {"id": "r43", "title": "פלאו בטבק", "category": "תוספות", "blocks": [{"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "3 כוסות אורז בסמטי", "bold": false, "kind": "ingredients"}, {"text": "6 כוסות מים רותחים", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "2 תפוחי אדמה קלופים וחתוכים לפרוסות", "bold": false, "kind": "ingredients"}, {"text": "2 בצלים חתוכים לפרוסות עגולים.", "bold": false, "kind": "ingredients"}, {"text": "חצי צרור עלי שמיר קצוצים", "bold": false, "kind": "ingredients"}, {"text": "¼ כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "¼ כוס שמן", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "בסיר להרתיח את האורז עם מלח עד לריכוך (לא בישול מלא),להעביר למסננת ולהוציא את כל הנוזלים.", "bold": false, "kind": "method"}, {"text": "בסיר רחב נשים ¼ כוס שמן ונניח את פרוסות הבצל ומעל את פרוסות תפו\"א ונטגן מעט.", "bold": false, "kind": "method"}, {"text": "נתבל בכורכום, מלח,פלפל שחור, נקצוץ את השמיר נוסיף אותו לאורז ונפזר את האורז מעל תפו\"א.", "bold": false, "kind": "method"}, {"text": "נבשל בערך כ-35 דק' על להבה נמוכה מאוד.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r44", "title": "קיצ'רי", "category": "תוספות", "blocks": [{"text": "מבשלים קיצ'רי ביום חמישי", "bold": false, "kind": "intro"}, {"text": "כמות מנות: 5", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "1 כוס אורז בסמטי", "bold": false, "kind": "ingredients"}, {"text": "¾ כוס עדשים כתומים", "bold": false, "kind": "ingredients"}, {"text": "1 כף מלח גס", "bold": false, "kind": "ingredients"}, {"text": "1 כף פפריקה מתוקה", "bold": false, "kind": "ingredients"}, {"text": "½ כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "2 כפות כמון", "bold": false, "kind": "ingredients"}, {"text": "10 שיני שום כתוש", "bold": false, "kind": "ingredients"}, {"text": "50 גר' חמאה", "bold": false, "kind": "ingredients"}, {"text": "4 כפות שמן זית.", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "שוטפים את האורז והעדשים הכתומים ומסננים היטב.", "bold": false, "kind": "method"}, {"text": "לתוך סיר מוסיפים 2 כפות שמן את האורז והעדשים פלפל שחור פפריקה מטגנים קלות, מוסיפים מים רותחים עם המלח גס, מבשלים על להבה בינונית במשך 20דקות.", "bold": false, "kind": "method"}, {"text": "(על כל כוס אורז להוסיף שתי כוסות מים רותחים,על ¾ כוס עדשים להוסיף חצי כוס מים רותחים).", "bold": false, "kind": "method"}, {"text": "במחבת:", "bold": false, "kind": "method"}, {"text": "שמים את החמאה, שמן זית שום כתוש, כמון וכמובן מטגנים מעט.", "bold": false, "kind": "method"}, {"text": "לאחר שהאורז בושל מוסיפים לסיר את תכולת המחבת ולערבב יחד היטב.", "bold": false, "kind": "method"}, {"text": "תוספות לבחירה מעל הקיצרי:", "bold": false, "kind": "method"}, {"text": "ביצה עין", "bold": false, "kind": "method"}, {"text": "ריויון מוקצף בבלנדר עם קוביות קרח", "bold": false, "kind": "method"}, {"text": "סלט ערבי.", "bold": false, "kind": "method"}, {"text": "בתאבון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 5", "photoStory": ["shoot-kichri-prep", "shoot-kichri-pot", "shoot-kichri-sides"], "image": "assets/album/shoot-kichri-serving.jpg"}, {"id": "r45", "title": "אורז צבעוני", "category": "תוספות", "blocks": [{"text": "כמות מנות: 4", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "כוס אורז בסמטי קלאסי", "bold": false, "kind": "ingredients"}, {"text": "1 בצל יבש קצוץ", "bold": false, "kind": "ingredients"}, {"text": "2 בצל ירוק", "bold": false, "kind": "ingredients"}, {"text": "צרור כוסברה", "bold": false, "kind": "ingredients"}, {"text": "צרור שמיר", "bold": false, "kind": "ingredients"}, {"text": "2 גזר מגורד", "bold": false, "kind": "ingredients"}, {"text": "כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "חצי כפית כורכום", "bold": false, "kind": "ingredients"}, {"text": "חמוציות (כמה שרוצים)", "bold": false, "kind": "ingredients"}, {"text": "צנוברים", "bold": false, "kind": "ingredients"}, {"text": "שקדים לבנים משובבים", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "מסננים כוס אורז במים. מחממים מעט שמן בסיר ומוסיפים את הבצל. מטגנים מעט את הבצל ומוסיפים את האורז. לאחר טיגון קל מוסיפים את יתר המצרכים ומערבבים הכל ביחד. מוסיפים כוס וחצי מים רותחים לסיר, מערבבים קלות על אש גבוהה ומביאים לרתיחה, מנמיכים את האש ומכסים את הסיר. מבשלים את האורז כ - 15 דק' על אש נמוכה. לאחר 15 דק' מכבים את האש ונותנים לאורז לנוח בתוך הסיר המכוסה עוד כ-5 דק'.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 4"}, {"id": "r46", "title": "שאלרם", "category": "תוספות", "blocks": [{"text": "שאלרם אוכלים ביום שבת", "bold": false, "kind": "intro"}, {"text": "כמות מנות: 6", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "לפת", "bold": false, "kind": "ingredients"}, {"text": "קורט מלח", "bold": false, "kind": "ingredients"}, {"text": "שקית תה", "bold": false, "kind": "ingredients"}, {"text": "2 כפות סילן", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": true, "kind": "section"}, {"text": "לשטוף היטב את הלפת, לסדר אותם בתוך סיר להוסיף את שאר המצרכים לכסות במי ברז ולהרתיח, לבשל עד השחמה (אפשר להכניס את הסיר לתנור כל הלילה בחום של 100 מעלות)", "bold": false, "kind": "method"}, {"text": "עד להשחמה והצטמצמות של המים.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": ["טיוטה לבדיקה: כמה לפת משתמשים?"], "servings": "כמות מנות: 6"}, {"id": "r47", "title": "מרק עדשים ירוקות", "category": "מרקים", "blocks": [{"text": "מצרכים:", "bold": false, "kind": "section"}, {"text": "1 כוס עדשים ירוקות שטופות ומסוננות", "bold": false, "kind": "ingredients"}, {"text": "1 בצל יבש", "bold": false, "kind": "ingredients"}, {"text": "10 שיני שום חתוכות", "bold": false, "kind": "ingredients"}, {"text": "סלרי קצוץ", "bold": false, "kind": "ingredients"}, {"text": "3 גזרים קצוצים", "bold": false, "kind": "ingredients"}, {"text": "עגבניה קלופה קצוצה", "bold": false, "kind": "ingredients"}, {"text": "כמון (לפי הטעם)", "bold": false, "kind": "ingredients"}, {"text": "מלח", "bold": false, "kind": "ingredients"}, {"text": "פלפל", "bold": false, "kind": "ingredients"}, {"text": "מים רותחים", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": false, "kind": "section"}, {"text": "בסיר גדול מטגנים את הבצל והשום, מוסיפים את הגזר והסלרי ומטגנים לריכוך, מוסיפים את העגבניה והעדשים, מוסיפים את התבלינים ומערבבים היטב. מוסיפים מים רותחים עד לשני שליש הסיר ומביאים לרתיחה. מכסים את הסיר במכסה ומבשלים על להבה בינונית כ-40 דק'.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": ""}, {"id": "r48", "title": "מרק שורבה", "category": "מרקים", "blocks": [{"text": "כמות : 6-8 מנות", "bold": true, "kind": "yield"}, {"text": "מצרכים:", "bold": true, "kind": "section"}, {"text": "2 כפיות שמן", "bold": false, "kind": "ingredients"}, {"text": "3/4כוס אורז", "bold": false, "kind": "ingredients"}, {"text": "2 בצלים חתוכים לקוביות", "bold": false, "kind": "ingredients"}, {"text": "3 עגבניות מגורדות", "bold": false, "kind": "ingredients"}, {"text": "2 כפות רסק עגבניות", "bold": false, "kind": "ingredients"}, {"text": "1/2כפית מלח", "bold": false, "kind": "ingredients"}, {"text": "1/4כפית פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "קורט כורכום", "bold": false, "kind": "ingredients"}, {"text": "4 נתחי עוף שונים", "bold": false, "kind": "ingredients"}, {"text": "5 -6 כוסות מים.", "bold": false, "kind": "ingredients"}, {"text": "אופן ההכנה:", "bold": false, "kind": "section"}, {"text": "שוטפים את האורז.", "bold": false, "kind": "method"}, {"text": "מחממים בסיר רחב את השמן ומטגנים קלות את הבצל, מוסיפים את העגבניות ורסק העגבניות ומערבבים.", "bold": false, "kind": "method"}, {"text": "מוסיפים את נתחי העוף, המלח, הפלפל, הכורכום והמים ומערבבים היטב.", "bold": false, "kind": "method"}, {"text": "מנמיכים את הלהבה ומבשלים 25-35 דקות.", "bold": false, "kind": "method"}, {"text": "לאחר מכן מוסיפים את האורז ומבשלים כ-15 דקות .", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות : 6-8 מנות"}, {"id": "r49", "title": "מרק שעועית לבנה וגרונות", "category": "מרקים", "blocks": [{"text": "כמות מנות: 6", "bold": false, "kind": "yield"}, {"text": "מצרכים:", "bold": false, "kind": "section"}, {"text": "3 כוסות שעועית לבנה שהושרתה לילה קודם (12 שעות) או שעועית לבנה של סנפרוסט", "bold": false, "kind": "ingredients"}, {"text": "2 גרונות הודו חתוכים / 10 גרונות עוף חתוכים", "bold": false, "kind": "ingredients"}, {"text": "1 בצל גדול קצוץ", "bold": false, "kind": "ingredients"}, {"text": "2 שיני שום חתוכות", "bold": false, "kind": "ingredients"}, {"text": "1 קופסה רסק עגבניות (100 גר')", "bold": false, "kind": "ingredients"}, {"text": "2 כפות פפריקה אדומה", "bold": false, "kind": "ingredients"}, {"text": "1 כפית כמון", "bold": false, "kind": "ingredients"}, {"text": "מלח, פלפל שחור", "bold": false, "kind": "ingredients"}, {"text": "אופן הכנה:", "bold": false, "kind": "section"}, {"text": "ניקוי הגרונות: להרתיח את הגרונות במלח ולסנן היטב.", "bold": false, "kind": "method"}, {"text": "הכנת המרק: לטגן בסיר את הבצל והשום עד להזהבה.", "bold": false, "kind": "method"}, {"text": "להוסיף את הגרונות ולהמשיך לטגן מעט.", "bold": false, "kind": "method"}, {"text": "להוסיף את השעועית, רסק העגבניות והתבלינים (מלבד הכמון, אותו נוסיף בסוף הבישול)ץ", "bold": false, "kind": "method"}, {"text": "לכסות את הסיר במי ברז עד לכיסוי + כמה ס\"מ נוספים (לא לפחד להוסיף מים, אנחנו לא רוצים שהמרק יצטמצם מדי).", "bold": false, "kind": "method"}, {"text": "לבשל במשך שעה וחצי לפחות.", "bold": false, "kind": "method"}, {"text": "בתום הבישול להוסיף את הכמון.", "bold": false, "kind": "method"}], "source": "Google Docs", "notes": [], "servings": "כמות מנות: 6"}], "introduction": ["הכל החל מצפיה באמי היקרה והאהובה עליה השלום שנפרדה ממני מהר מאוד… ולי היא הותירה את קסמי ידיה, את פאר מטבחה ותבשיליה, ריחות וטעמים בלתי נשכחים.", "בילדותי ביתי היה בית מאוד פתוח ומארח על בסיס קבוע שסופי שבוע בו זכורים לי היטב - המון דודים ודודות ובני דודים המתארחים בביתנו וקבלת הפנים של אימי שתמיד היתה בזרועות פתוחות, המטבח היה מלא בסירים גדולים ותבשילים עיראקים כמובן מכל טוב.", "בתקופת ההתבגרות הייתי מאוד בררנית באוכל, עדיין לא נפתחתי למאכלים האותנטיים שאמא בישלה. אהבתי בעיקר שניצל וצ'יפס, ולא אשקר גם שמרתי על פיגורה בתקופת ההתבגרות. כשהייתי בתיכון היתה תקופה שאמא אושפזה ונעדרה מהבית, לקחתי חלק מאוד נכבד במטלות הבית כולל בישול ועמידה במטבח במשך שעות, זאת היתה תקופת \"ההכשרה שלי\".", "זכור לי שאבא ז\"ל לימד אותי באותם ימים לבשל כמה תבשילים מהמטבח העיראקי.", "בשנות ה-80 התגייסתי לצה\"ל, אלו היו שנים שבהן לא נכנסתי למטבח, לקחתי פסק זמן, התגוררתי במדינת ת\"א ושם נפתחתי לקולינריה חדשה, הכרתי מטבחים חדשים. בסוף שנות ה-80 נישאתי, הקמתי משפחה משלי, נולדו לי בנותיי האהובות דיקלה, צאלה ואלומה. לבנות שלי כל יום חיכו סירים על הגז - תבשילים שלימדה אותי אמא, היה חשוב לי שהן יאהבו את האוכל העיראקי ולהנכיח אותו בביתי וחלילה לא לשכוח מהיכן באתי והיכן ספגתי את רזי הבישול העיראקי.", "הקפדתי לארח בערבי חג את משפחתי המורחבת ולבשל מכל טוב.", "לסיום אספר שאת ספר הבישול שלי שנכתב בקפידה על ידי הוא תוצר של כל השנים בהן אני נהנית לבשל, לארח ולשמר את המטבח העיראקי מבית אמא."], "dedication": "אני מקדישה ספר זה לזכרה של אימי שושנה שלימדה אותי את כל רזי המטבח שכעת מועברים אליכם קוראים יקרים.", "kubbaIntro": ["קובה זה אוכל מנחם, כדור בשר שעטוף בסולת בדרך כלל – בעיראק השתמשו בעיקר בבורגול למעטפת.", "יש המון סוגי קובות אך לא את כולן הכנתי בבית.", "את הקובות למדתי להכין מסבתא שושנה אמא שלי ז\"ל שלימדה אותי לבשל את כל האוכל העיראקי.", "טיפים טובים להכנת הקובות:", "לבחור סולת מסוג טוב", "רצוי להכין את מעטפת הקובה דקה אך לא דקה מידי כדי שהכדור לא יתפרק בבישול", "את מילוי הבשר כדאי לקצוץ דק ולתבל עדין", "חשוב מאוד לתת לבצק לנוח מעט לפני שעובדים איתו"]};